'use client';

import { useState } from 'react';

import { MotionNumber } from '@/components/core/motion-number';
import { useAutoplay } from '@/registry/ndeko/hooks/use-autoplay';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import {
  PRESS_LEAD_MS,
  spokenUnless,
  usePress,
} from '@/registry/ndeko/lib/demonstration';
import { PlugIcon } from '@/registry/ndeko/lib/icons';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';

import { AppTile, type Anchor } from './app-tile';
import {
  APPS,
  appOf,
  DEMO_CONNECT,
  RESTING_ID,
  SECTION,
  type AppId,
} from './data';

const LOOP_AFTER_MS = 2800;

function anchorOf(index: number): Anchor {
  const lastIndex = APPS.length - 1;
  if (index <= 1) {
    return 'start';
  }
  if (index >= lastIndex - 1) {
    return 'end';
  }
  return 'center';
}

/** Under reduced motion nothing walks, so the shelf rests with one card open. */
function shownIdOf(activeId: AppId | null, shouldReduceMotion: boolean) {
  if (activeId === null && shouldReduceMotion) {
    return RESTING_ID;
  }
  return activeId;
}

function tabStopIdOf(shownId: AppId | null) {
  if (shownId === null) {
    return APPS[0].id;
  }
  return shownId;
}

function targetIndexOf(key: string, index: number) {
  const lastIndex = APPS.length - 1;
  if (key === 'ArrowRight') {
    const after = index + 1;
    return Math.min(lastIndex, after);
  }
  if (key === 'ArrowLeft') {
    const before = index - 1;
    return Math.max(0, before);
  }
  if (key === 'Home') {
    return 0;
  }
  if (key === 'End') {
    return lastIndex;
  }
  return null;
}

export default function AiProduct06() {
  const [activeId, setActiveId] = useState<AppId | null>(null);
  const [connected, setConnected] = useState<AppId[]>([]);
  const [message, setMessage] = useState('');
  const [isPointerInside, setIsPointerInside] = useState(false);
  const { pressed, press } = usePress<string>();
  const shouldReduceMotion = usePrefersReducedMotion();

  function connect(id: AppId) {
    const app = appOf(id);
    const isConnected = connected.includes(id);
    setActiveId(id);
    if (isConnected) {
      return;
    }
    setConnected((current) => [...current, id]);
    setMessage(`${app.name} connected`);
  }

  function resetDemonstration() {
    setActiveId(null);
    setConnected([]);
    setMessage('');
  }

  const steps = [
    { after: 900, run: () => setActiveId(APPS[0].id) },
    { after: 1800, run: () => setActiveId(APPS[1].id) },
    { after: 1800, run: () => setActiveId(APPS[2].id) },
    { after: 1200, run: () => press(`connect-${DEMO_CONNECT}`) },
    { after: PRESS_LEAD_MS, run: () => connect(DEMO_CONNECT) },
    { after: 1800, run: () => setActiveId(APPS[3].id) },
    { after: 1800, run: () => setActiveId(APPS[4].id) },
  ];
  const { ref, isAutoplaying } = useAutoplay<HTMLElement>(steps, {
    loopAfter: LOOP_AFTER_MS,
    onReset: resetDemonstration,
    isEnabled: !isPointerInside,
  });
  const shownId = shownIdOf(activeId, shouldReduceMotion);
  const tabStopId = tabStopIdOf(shownId);
  const hasActive = shownId !== null;
  const spoken = spokenUnless(isAutoplaying, message);

  function enterRow(event: React.PointerEvent<HTMLElement>) {
    if (event.pointerType === 'mouse') {
      setIsPointerInside(true);
    }
  }

  function leaveRow(event: React.PointerEvent<HTMLElement>) {
    if (event.pointerType !== 'mouse') {
      return;
    }
    setIsPointerInside(false);
    setActiveId(null);
  }

  /** A click on a button that takes no focus (Safari) leaves no next element: the card stays for it. */
  function leaveFocus(event: React.FocusEvent<HTMLUListElement>) {
    const next = event.relatedTarget;
    if (!(next instanceof Node)) {
      return;
    }
    const isStillInside = event.currentTarget.contains(next);
    if (!isStillInside) {
      setActiveId(null);
    }
  }

  function moveFocus(event: React.KeyboardEvent<HTMLUListElement>) {
    if (event.key === 'Escape') {
      setActiveId(null);
      return;
    }
    const target = event.target;
    if (!(target instanceof HTMLElement)) {
      return;
    }
    const currentId = target.dataset.appTile;
    const index = APPS.findIndex((app) => app.id === currentId);
    if (index < 0) {
      return;
    }
    const nextIndex = targetIndexOf(event.key, index);
    if (nextIndex === null) {
      return;
    }
    event.preventDefault();
    const next = APPS[nextIndex];
    const tile = ref.current?.querySelector<HTMLElement>(
      `[data-app-tile="${next.id}"]`
    );
    tile?.focus();
  }

  return (
    <section ref={ref} className='@container'>
      <div className='mx-auto flex max-w-3xl flex-col gap-10 px-4 py-16 @2xl:px-6 @2xl:py-24'>
        <header className='flex flex-wrap items-end justify-between gap-x-6 gap-y-3'>
          <div className='flex max-w-xl flex-col gap-3'>
            <p className='text-primary-ink flex items-center gap-1.5 text-[13px] font-medium'>
              <PlugIcon className='size-4' />
              {SECTION.label}
            </p>
            <h2 className='text-2xl font-semibold text-balance @2xl:text-3xl'>
              {SECTION.title}
            </h2>
            <p className='text-muted-foreground text-base text-pretty'>
              {SECTION.lead}
            </p>
          </div>
          <p className='text-muted-foreground flex items-baseline gap-1 text-[13px]'>
            <MotionNumber
              value={connected.length}
              className='text-foreground'
            />
            of {APPS.length} connected
          </p>
        </header>
        <ul
          aria-label='Apps'
          onKeyDown={moveFocus}
          onBlur={leaveFocus}
          onPointerEnter={enterRow}
          onPointerLeave={leaveRow}
          className='flex justify-center gap-2 pb-44 @lg:gap-5 @2xl:gap-6'
        >
          {APPS.map((app, index) => (
            <AppTile
              key={app.id}
              app={app}
              anchor={anchorOf(index)}
              isActive={shownId === app.id}
              isDimmed={hasActive && shownId !== app.id}
              isConnected={connected.includes(app.id)}
              isTabStop={tabStopId === app.id}
              pressed={pressed}
              onActivate={setActiveId}
              onConnect={connect}
            />
          ))}
        </ul>
      </div>
      <LiveRegion message={spoken} />
    </section>
  );
}

'use client';

import { AnimatePresence, motion, type Transition } from 'motion/react';
import { useId } from 'react';

import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { pressedSolidOf } from '@/registry/ndeko/lib/demonstration';
import { EASE_OUT_STRONG } from '@/registry/ndeko/lib/motion-presets';
import { cn } from '@/registry/ndeko/lib/utils';
import { BrandTile } from '@/registry/ndeko/ui/brand-tile';
import { Button } from '@/registry/ndeko/ui/button';
import { Swap } from '@/registry/ndeko/ui/chat-motion';
import { DrawnCheck } from '@/registry/ndeko/ui/drawn-check';

import type { App } from './data';

export type Anchor = 'start' | 'center' | 'end';

/** The cards of the outer tiles hang from the edge of the row, so none leaves the block. */
const ANCHOR_CLASS: Record<Anchor, string> = {
  start: 'start-0 origin-top-left',
  center: 'left-1/2 -translate-x-1/2 origin-top',
  end: 'end-0 origin-top-right',
};

const LIFT: Transition = { duration: 0.22, ease: EASE_OUT_STRONG };

const LEAVE: Transition = { duration: 0.1, ease: EASE_OUT_STRONG };

function liftOf(shouldReduceMotion: boolean) {
  if (shouldReduceMotion) {
    return {
      initial: { opacity: 0 },
      animate: { opacity: 1, transition: LIFT },
      exit: { opacity: 0, transition: LEAVE },
    };
  }
  return {
    initial: { opacity: 0, scale: 0.94, y: -12 },
    animate: { opacity: 1, scale: 1, y: 0, transition: LIFT },
    exit: { opacity: 0, scale: 0.96, y: -6, transition: LEAVE },
  };
}

function toneOf(isActive: boolean, isDimmed: boolean) {
  if (isActive) {
    return 'bg-foreground/[0.09] -translate-y-0.5';
  }
  if (isDimmed) {
    return 'bg-foreground/[0.04] opacity-40';
  }
  return 'bg-foreground/[0.04]';
}

function stateWordOf(isConnected: boolean) {
  if (isConnected) {
    return 'connected';
  }
  return 'not connected';
}

type AppTileProps = {
  app: App;
  anchor: Anchor;
  isActive: boolean;
  isDimmed: boolean;
  isConnected: boolean;
  isTabStop: boolean;
  pressed: string | null;
  onActivate: (id: App['id']) => void;
  onConnect: (id: App['id']) => void;
};

export function AppTile({
  app,
  anchor,
  isActive,
  isDimmed,
  isConnected,
  isTabStop,
  pressed,
  onActivate,
  onConnect,
}: AppTileProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const cardId = useId();
  const lift = liftOf(shouldReduceMotion);
  const label = `${app.name}, ${stateWordOf(isConnected)}`;
  let tabIndex = -1;
  if (isTabStop) {
    tabIndex = 0;
  }
  let describedBy: string | undefined;
  if (isActive) {
    describedBy = cardId;
  }

  function connectFromKeyboard(event: React.KeyboardEvent<HTMLButtonElement>) {
    const isEnter = event.key === 'Enter';
    const isSpace = event.key === ' ';
    if (isEnter || isSpace) {
      event.preventDefault();
      onConnect(app.id);
    }
  }

  return (
    <li
      data-app-item={app.id}
      onPointerEnter={(event) => {
        if (event.pointerType === 'mouse') {
          onActivate(app.id);
        }
      }}
      className='relative'
    >
      <button
        type='button'
        data-app-tile={app.id}
        aria-label={label}
        aria-describedby={describedBy}
        tabIndex={tabIndex}
        onFocus={() => onActivate(app.id)}
        onClick={() => onActivate(app.id)}
        onKeyDown={connectFromKeyboard}
        className={cn(
          'focus-visible:ring-ring focus-visible:ring-offset-background relative flex size-12 cursor-pointer items-center justify-center rounded-2xl transition-[background-color,opacity,translate] duration-150 ease-(--ease-out-strong) outline-none focus-visible:ring-2 focus-visible:ring-offset-2 @xs:size-14 @md:size-20',
          toneOf(isActive, isDimmed)
        )}
      >
        <BrandTile brand={app.brand} size='2xl' />
        <AnimatePresence>
          {isConnected && (
            <span className='absolute -end-1 -top-1'>
              <DrawnCheck tone='success' />
            </span>
          )}
        </AnimatePresence>
      </button>
      <AnimatePresence>
        {isActive && (
          <motion.div
            key='card'
            id={cardId}
            initial={lift.initial}
            animate={lift.animate}
            exit={lift.exit}
            className={cn(
              'surface-raised absolute top-full z-10 mt-2 flex w-60 flex-col gap-3 rounded-xl p-3 @md:w-64',
              ANCHOR_CLASS[anchor]
            )}
          >
            <div className='flex items-center gap-2'>
              <BrandTile brand={app.brand} size='md' />
              <p className='text-[13px] font-medium'>{app.name}</p>
            </div>
            <p className='text-muted-foreground text-xs text-pretty'>
              {app.line}
            </p>
            <Swap swapKey={stateWordOf(isConnected)} className='self-start'>
              {!isConnected && (
                <Button
                  type='button'
                  size='sm'
                  onClick={() => onConnect(app.id)}
                  className={pressedSolidOf(pressed === `connect-${app.id}`)}
                >
                  Connect {app.name}
                </Button>
              )}
              {isConnected && (
                <span className='text-success-foreground flex h-7 items-center gap-1.5 text-xs font-medium'>
                  <DrawnCheck tone='success' entrance='draw' />
                  Connected
                </span>
              )}
            </Swap>
          </motion.div>
        )}
      </AnimatePresence>
    </li>
  );
}

import type { BrandSlug } from '@/registry/ndeko/lib/brand-logos';

export const SECTION = {
  label: 'Connected apps',
  title: 'The apps your agent can use',
  lead: 'Point at an app to see what the agent does with it, then connect it.',
};

export type AppId = 'notion' | 'linear' | 'github' | 'calendar' | 'gmail';

export type App = {
  id: AppId;
  name: string;
  brand: BrandSlug;
  line: string;
};

export const APPS: App[] = [
  {
    id: 'notion',
    name: 'Notion',
    brand: 'notion',
    line: 'Reads your pages and writes the weekly summary',
  },
  {
    id: 'linear',
    name: 'Linear',
    brand: 'linear',
    line: 'Opens issues and moves them when the work is done',
  },
  {
    id: 'github',
    name: 'GitHub',
    brand: 'github',
    line: 'Reviews pull requests and drafts release notes',
  },
  {
    id: 'calendar',
    name: 'Google Calendar',
    brand: 'googlecalendar',
    line: 'Finds a slot that suits everyone you invite',
  },
  {
    id: 'gmail',
    name: 'Gmail',
    brand: 'gmail',
    line: 'Drafts replies and waits for your go before sending',
  },
];

export const RESTING_ID: AppId = 'linear';

export const DEMO_CONNECT: AppId = 'github';

export function appOf(id: AppId) {
  const app = APPS.find((candidate) => candidate.id === id);
  return app ?? APPS[0];
}
